 if(motion){const p=Math.min((now-motion.start)/motion.duration,1),ease=p*p*(3-2*p);player.position.lerpVectors(motion.from,motion.to,ease);player.position.y+=Math.sin(p*Math.PI)*.12;if(p===1){position={...motion.next};const shouldFall=motion.fall;motion=null;if(shouldFall){falling={time:now,start:player.position.clone()};toast('There’s no ground here. The white stone will catch you.');}else{if(at(position.x,position.z).mask===3)checkpoint={...position};collect();}}}
